// The English help, part two: the sections graph … env of help.ts (same ids and order).
// Every <dt> keeps its Russian term in data-term, so a "?" of the interface (which passes the Russian term) finds it.
import type { HelpSection } from './help'
import { icon } from './icons'

// ---- the graph's pictures: who works (the header's colour) and what a port carries, as on the canvas (lib/graphDoc.ts)
const WHO: Record<string, [string, string]> = {
  h3: ['var(--accent)', 'model shoots'], writer: ['var(--ok)', 'Writer (LLM)'], ffmpeg: ['#378ADD', 'join, ffmpeg and RTX'],
  krea: ['#f59e0b', 'Krea 2 draws'], v2v: ['#14b8a6', 'clip rebuild'], facefix: ['#2dd4bf', 'Krea 2 and LTX 2.3 fix faces'],
  user: ['var(--faint)', 'your data'], none: ['var(--rule-3)', 'canvas only'],
}
const PORT: Record<string, [string, string]> = {
  text: ['var(--soft)', 'text'], look: ['var(--ok)', 'look'], image: ['#e879f9', 'picture'], clip: ['#378ADD', 'scene'],
  video: ['#378ADD', 'video'], audio: ['#eab308', 'sound'], lora: ['var(--accent-hi)', 'LoRA'],
}
const pt = (name: string, type: string) => `<span class="pt" style="--p:${PORT[type][0]}"><i></i>${name}</span>`
const WHO_CHIPS = Object.entries(WHO).filter(([k]) => k !== 'none').map(([, [c, n]]) => `<span class="who-chip" style="--h:${c}"><i></i>${n}</span>`).join('')
const PORT_CHIPS = Object.entries(PORT).filter(([k]) => k !== 'video').map(([k, [, n]]) => pt(k === 'clip' ? 'scene, video' : n, k)).join('')
// a node as a card: the <dt> shows the English name and keeps the Russian one in data-term (the canvas's "?" passes it)
// a port with what to plug into it / where it goes: a row of the card's list
type Port = [string, string, string]
const portRows = (ins: Port[], outs: Port[]) => !ins.length && !outs.length ? '' : `<div class="nc-list">${
  ins.length ? `<span class="nc-h">Inputs</span>${ins.map(([n, t, h]) => `<div class="nc-row in">${pt(n, t)}<span class="nc-hint">${h}</span></div>`).join('')}` : ''}${
  outs.length ? `<span class="nc-h">Outputs</span>${outs.map(([n, t, h]) => `<div class="nc-row out">${pt(n, t)}<span class="nc-hint">${h}</span></div>`).join('')}` : ''}</div>`
const nodeCard = (titleRu: string, titleEn: string, who: string, ic: string, ins: Port[], outs: Port[], text: string) =>
  `<div class="node-card" style="--h:${WHO[who][0]}"><dt data-term="${titleRu}">${icon(ic, 15)}${titleEn}</dt><dd>${portRows(ins, outs)}${text.startsWith('<') ? text : `<p>${text}</p>`}</dd></div>`

// «Two endings» as a picture: scenes 1-2 shared, two third scenes, two assemblies, two outputs
const GW = 118, GH = 56
const gBox = (x: number, y: number, title: string, who: string, sub: string) => `<g transform="translate(${x} ${y})">
  <rect width="${GW}" height="${GH}" rx="9" class="gd-node"/><rect x="10" y="0" width="${GW - 20}" height="3" rx="1.5" fill="${WHO[who][0]}"/>
  <text x="11" y="23" class="gd-t">${title}</text><text x="11" y="41" class="gd-s">${sub}</text></g>`
const gEdge = (x1: number, y1: number, x2: number, y2: number, type: string, faint = false) =>
  `<path d="M${x1} ${y1} C${x1 + 36} ${y1} ${x2 - 36} ${y2} ${x2} ${y2}" stroke="${PORT[type][0]}" class="gd-e${faint ? ' faint' : ''}"/>
  <circle cx="${x1}" cy="${y1}" r="3.5" fill="${PORT[type][0]}"/><circle cx="${x2}" cy="${y2}" r="3.5" fill="${PORT[type][0]}"/>`
const S1 = [16, 92], S2 = [176, 92], KA = [336, 24], KB = [336, 160], JA = [490, 24], JB = [490, 160], OA = [652, 24], OB = [652, 160]
const R = (b: number[], dy: number) => [b[0] + GW, b[1] + dy] as const, L = (b: number[], dy: number) => [b[0], b[1] + dy] as const
const GRAPH_DIAGRAM = `<figure class="graph-pic" aria-label="Two endings: shared scenes 1 and 2, two different third scenes, two joins and two outputs">
<svg viewBox="0 0 786 236" role="img">
${[S1, S2, KA, KB].map((s) => [JA, JB].filter((j) => !(s === KA && j === JB) && !(s === KB && j === JA)).map((j) => gEdge(...R(s, 40), ...L(j, 38), 'clip', true)).join('')).join('')}
${gEdge(...R(S1, 20), ...L(S2, 20), 'image')}${gEdge(...R(S2, 20), ...L(KA, 20), 'image')}${gEdge(...R(S2, 20), ...L(KB, 20), 'image')}
${gEdge(...R(JA, 28), ...L(OA, 28), 'video')}${gEdge(...R(JB, 28), ...L(OB, 28), 'video')}
${gBox(S1[0], S1[1], 'Scene 1', 'h3', 'shared')}${gBox(S2[0], S2[1], 'Scene 2', 'h3', 'from scene 1’s frame')}
${gBox(KA[0], KA[1], 'Ending A', 'h3', 'from scene 2’s frame')}${gBox(KB[0], KB[1], 'Ending B', 'h3', 'from scene 2’s frame')}
${gBox(JA[0], JA[1], 'Join A', 'ffmpeg', '1 · 2 · A')}${gBox(JB[0], JB[1], 'Join B', 'ffmpeg', '1 · 2 · B')}
${gBox(OA[0], OA[1], 'Output A', 'ffmpeg', '1080p')}${gBox(OB[0], OB[1], 'Output B', 'ffmpeg', '1080p')}
<text x="16" y="178" class="gd-s">scenes 1–2 are shot once</text><text x="16" y="194" class="gd-s">and go into both versions</text>
</svg>
<figcaption>The «Two endings» template. <span style="color:#e879f9">Pink</span> links: a scene’s last frame goes into the start of the next one; <span style="color:#378ADD">blue</span> links: shot scenes go into the join, the join into the output.</figcaption>
</figure>`

export const PART_B: HelpSection[] = [
  { id: 'graph', group: 'Storyboard', title: 'Graph', html: `
<p>«Graph» in the «Cards / Graph» switch next to the title opens the same storyboard on a canvas: what each scene is shot from and where it goes next. The storyboard’s links are edited right on the diagram: drag a scene’s «frame» to the «start» of a later one, and that one becomes a continuation from this frame (a cutaway and a return); a click on a link selects the scene it leads into; the scene panel has «Start», «Takes» and «Scene LoRA». Everything is saved to the storyboard at once. Text, people and camera live in the cards; a separate graph with branches and a «Montage» is «Copy — project graph» at the top of the side panel, under the title (when nothing is selected).</p>
<dl>
<dt data-term="Узлы">Nodes</dt><dd>On the left: the heroes (or the world, in a video without people), the style and the LoRA. In the middle: the scenes, one chain per row; a long chain wraps every 6 scenes. On the right: the join, the music and the output. The header’s color is who does the work: purple, the model shoots; green, the Writer; blue, the join and RTX; gray, your files.</dd>
<dt data-term="Связи">Links</dt><dd>A scene’s last frame goes into the continuation’s «start» (in the chain’s color). The hero’s look goes into the «who» of the scene that opens a chain or changes the cast. A photo for Ref2VA goes into «faces», as a yellow dashed line. A scene’s own photo goes into its «start». Every shot scene goes into the join. The style and the LoRA act on all scenes, so they have no links.</dd>
<dt data-term="Состояние сцены">Scene state</dt><dd>The same words as on the «Video» screen: «from cache», «93 s», «step 5/8», «waiting for frame». Two more words exist only here: «will reshoot», the scene changed after it was shot, and «in cache», a frame with this key is already shot, though there is no finished video.</dd>
<dt data-term="Щелчок по узлу">Clicking a node</dt><dd>Highlights its links and dims the rest. On the right: the scene’s video, where it starts from, who is in the frame, the seed, the frame key and «Prompt for the model». «Open in storyboard» takes you to this scene in the cards.</dd>
<dt data-term="Холст">Canvas</dt><dd>The wheel zooms, dragging pans, as in ComfyUI. «Whole graph» shows the entire video. A long video opens on its first rows. «Go to scene» on the right takes you to a scene by its number.</dd>
<dt data-term="Копия — проект-граф">Copy — project graph</dt><dd>Makes a new project graph from the storyboard: each scene becomes a «Prompt» node with its prompt word for word and a «Scene» node with its seed. The keys are the same, so shot scenes come from the storyboard’s cache; nothing is copied or reshot. The storyboard itself stays as it was.</dd>
</dl>` },

  { id: 'edit', group: 'Shooting and video', title: 'Montage', html: `
<p class="lead">The fourth step: the shot scenes on a timeline. Here you trim the start and end of scenes, reorder chains, add transitions and put in your own track. Nothing is reshot: «Build video» joins the scenes from the cache following the montage.</p>
<dl>
<dt data-term="Обрезка">Trimming</dt><dd>Drag a clip’s left edge to trim the scene’s start, its right edge to trim the end; the scenes after it shift on their own, and the player shows the frame at the cut. For precision, use the clip panel: «Start» and «End» in seconds within the shot, the ‹ › arrows step by a frame. A clip is no shorter than 0.5 s. «As it was» brings the whole scene back.</dd>
<dt data-term="Экран">Screen</dt><dd>Like an editing program, all in one window: at the top, the project bar — the length, whether the montage is saved and whether the video is built from it, one main button: «Build video», or «Open the video» once the video is built from this montage; below it, the player above the timeline, and at the side the panel, a full-height column in four tabs: «Clip», «Color», «Sound», «Output». The selection opens its own: a clip, a seam or a piece «Over» opens «Clip», a sound or the track opens «Sound»; a clip picked while «Color» is open stays on «Color» — it is the one being colored. Empty «Over», «Music» and «Sounds» lanes are a thin line with their «+». The border above the timeline can be dragged to make the player bigger or smaller (a double click restores it). The panel moves by its handle, as on other screens: right, left or as a window.</dd>
<dt data-term="Стыки">Cuts</dt><dd>Above every cut between two clips is an icon showing what kind of cut it is: a <b>link</b> in the chain’s color, seamless (a continuation from the last frame, the picture flows on); a <b>yellow triangle</b>, a jump (the chain’s cut is trimmed, a different take comes before the continuation, or the speed is not 1×); a <b>bar</b>, a cut between different scenes; a <b>spark</b>, a flash; <b>two circles</b>, a dissolve; a <b>black dot</b>, through black. A click on the icon opens the cut in the panel: the two clips on either side, why it jumps, «Restore the cut» (ends as shot, the same take, 1×) or «Hide with a dissolve», the transition and its length, «Play the cut» from one and a half seconds before it (a double click on the icon does the same). <kbd>Delete</kbd> on a cut removes the transition. With nothing selected, the panel lists the jumping cuts.</dd>
<dt data-term="Переходы">Transitions</dt><dd>Each cut has one: <b>cut</b> (straight), <b>flash</b> (a cut with a white flash for 4 frames, doesn’t change the length; in a clip from a song, loud parts start this way by default), <b>dissolve</b> (picture and sound blend) or <b>through black</b>; a transition lasts 0.2–2 s. A dissolve shortens the video by its length: the scenes overlap. The selected clip’s panel has a «Cut before the clip» line; a click takes you to the cut.</dd>
<dt data-term="Цепочки">Chains</dt><dd>A continuation starts from the previous scene’s last frame, so the scenes of a chain always stay together: drag a clip and the whole chain moves, a blue bar shows where. An untrimmed cut inside a chain is seamless (a link above the cut). Trim such a cut and the picture will jump: a yellow triangle above the cut; «Restore the cut» in the cut’s panel puts it back as it was.</dd>
<dt data-term="Разрез, копия, убрать">Split, copy, remove</dt><dd><kbd>S</kbd> (or «Split») splits the clip at the playhead: two parts of one scene, the second continues the first seamlessly, and each can be trimmed, moved within the chain as a copy, slowed down. <kbd>Ctrl</kbd> <kbd>D</kbd> puts a copy of the clip right after it (a repeated moment, a «freeze frame» from a slowed copy). <kbd>Delete</kbd> removes the clip; if a scene has no clips left, it leaves the video but stays in the storyboard, and «Removed from the video» in the montage panel puts it back in place.</dd>
<dt data-term="Дубли">Takes</dt><dd>If a scene has several takes («Another take» in the storyboard), the clip panel has «Take» with thumbnails: the clip can use any of them, the storyboard doesn’t change (★ is the storyboard’s take, the continuations start from its frame). A different take before a continuation makes the cut jump; two parts of one take are seamless. The clip shows a «t» badge.</dd>
<dt data-term="Скорость">Speed</dt><dd>0.5–2× for each clip: the scene’s picture and sound slow down or speed up together (the sound keeps its pitch). The clip shows a «2×» badge; its length in the video changes and the scenes after it shift. A cut with a different speed is not seamless: a yellow triangle above the cut.</dd>
<dt data-term="Отмена">Undo</dt><dd><kbd>Ctrl</kbd> <kbd>Z</kbd> undoes any montage edit, even «As in the storyboard»; <kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>Z</kbd> or <kbd>Ctrl</kbd> <kbd>Y</kbd> redoes. Quick edits in a row (a slider) count as one step. The undo and redo buttons are above the timeline. <kbd>Esc</kbd> clears the selection, <kbd>M</kbd> turns the «Magnet» on and off. All keys: «Keys» in the project bar or <kbd>?</kbd>.</dd>
<dt data-term="Звук сцен">Scene sound</dt><dd>Plays with its scene’s picture. Each clip has its own volume (0–200 %, the «Scene sound» slider): quieter for background under a line from the next scene, louder for a quiet line. The track shows the sound’s waveform. Sound is cut in whole frames together with its picture and is never shifted, so lines stay on the lips. At a cut, a short 0.03 s smoothing prevents clicks; at a dissolve, the sounds blend.</dd>
<dt data-term="Музыка">Music</dt><dd>Your track, the same one as on the «Video» screen: volume, «scene sound under it», the second to start from, fade-in and fade-out. A click on the «Music» track shows these settings in the panel. No track: «Own track». <b>Ducks under scenes</b> is a 0–100 % slider («off» disables it): the track gets quieter on its own where scenes are loud (a line, a scream) and comes back in the pauses (a compressor keyed by the scene sound, 10:1 at 100 %); you hear it in the built video, not in the preview.</dd>
<dt data-term="Магнит">Magnet</dt><dd>A button above the timeline, present when the video has your own track; <kbd>M</kbd> does the same. When on, clip trimming and sounds snap to the track’s nearest beat, and the time ruler shows beats and bars (when the zoom allows). The choice is remembered in this browser.</dd>
<dt data-term="Склейки на доли">Cuts on beats</dt><dd>In the same place: every cut moves to the track’s beat before it, a clip gets shorter by less than a beat. Seamless chain cuts are left alone. If everything is already on beats, it will say so.</dd>
<dt data-term="Звуки">Sounds</dt><dd>The «Sounds» track holds your files (mp3, wav, m4a, flac, ogg): «+ Sound» puts a file at the playhead. A sound can be dragged along the track, its edges trim its start and end; the panel has the second of the video it starts at, volume, fade-in, fade-out, copy. Sounds play over the scene sound and the track; the files are kept in the project’s <code>sounds</code> folder.</dd>
<dt data-term="Поверх">Over</dt><dd>The «Over» lane above the video: a piece of the shot of any scene of the video (any shot take of it) covers the picture on its stretch, while the sound, the video’s length and the cuts stay as they were — an insert, another take over, a cutaway without changing the montage. «+ Over» puts a piece of the scene under the playhead at the playhead — another take of it if one is shot; the panel picks the scene, the take, the second of the video and the piece of the shot. Drag it along the lane (the magnet snaps it to beats), its edges trim it. The video’s color goes over it too; in DaVinci it goes to track V2 without sound.</dd>
<dt data-term="Цвет ролика">Video color</dt><dd>The «Color» tab of the montage panel: at the top the look, one color for all scenes: «As shot», «Film», «Warm», «Cool», «Teal and orange», «Black and white» or your own LUT, «Load LUT (.cube)». <b>Match scenes’ color</b>: each clip is pulled 60 % toward the video’s average color and contrast, so scenes from different models and takes stop jumping in color. You see it in the built video; the preview shows it as shot. No frames are added or lost, the cuts stay in place. Below: <b>LUT strength</b> (your table only part of the way: 50 % is halfway), <b>Vignette</b> (darker towards the corners) and <b>Film grain</b> (new in every frame; still in the preview), over the whole video. <b>Before / after</b>: hold the button and the player shows the video as shot, without any color; let go and the color is back.</dd>
<dt data-term="Плеер">Player</dt><dd>Plays the montage in the browser: two videos taking turns, dissolves and black done with transparency, the scene sound and the track at their own volume. Space plays / pauses, ← → steps a frame, Shift + ← → a second, Home / End go to the start and end. It may stutter slightly at a cut; in the built video everything is exact.</dd>
<dt data-term="Собрать ролик">Build video</dt><dd>A queue job, like «Shoot video»: scenes not yet shot get shot, the rest come from the cache; then the join following the montage, the track, 1080p / 4K / HDR / 48 fps. The button is always in the project bar, and next to it whether the video is built from this montage («Video built from the montage», «from an earlier montage», «not built», «There are unshot scenes», and then «Shoot and build»). On the «Video» screen, after montage edits: «Build from the montage».</dd>
<dt data-term="Связь с раскадровкой">Link to the storyboard</dt><dd>The montage is stored in the project, its scenes by their own number, which doesn’t change. A reshot scene stays the same clip with its trims; a deleted one leaves; a new one goes after the scene before it. «As in the storyboard» erases the montage edits. Without edits, the video is built the same way as always.</dd>
<dt data-term="Для DaVinci Resolve">For DaVinci Resolve</dt><dd>The button in the montage panel (nothing selected) asks for a folder (next time the dialog opens in the same place), creates a «Video name · Resolve» folder in it with an FCPXML timeline and the files it plays, and opens it. Exporting again recreates this folder. If a foreign folder with that name is already there, it isn’t touched: the export goes to «… 2». In Resolve: File → Import → Timeline. The scenes go onto a video track with their sound, with trims, speed, dissolves and volume. The track and the sounds go onto their own tracks, with volume and fades. A flash becomes a marker. Track ducking and the video color are not carried over: Resolve does them its own way, and your LUT is placed next to the timeline. An unshot scene arrives as an empty gap of its length labeled «Scene N — not shot»: shoot it and export again. The graph’s montage can’t be exported this way yet.</dd>
</dl>` },

  { id: 'graph-edit', group: 'Graph', title: 'Project graph', html: `
<p class="lead">A video built from nodes on a canvas: scenes, photos, LoRA, joins, music and outputs, with any links between them. The graph is for branches and versions: two endings from shared scenes, a short and a long version, a scene that starts from a frame of any other one. For a straight «idea → scenes» video, the storyboard is simpler.</p>
${GRAPH_DIAGRAM}
<div class="tip"><b>How to start.</b> «Graph» among the ways to start on the home screen, then «Choose a template»: a template or an empty canvas with one scene. The first time, the easiest is the «Idea → Writer → video» template: the idea and the heroine are already filled in and connected to the Writer, and a note next to them says what to press. «Copy — project graph» from a storyboard gives the same storyboard as nodes, with all shot scenes taken from its cache.</div>
<ol class="flow steps">
  <li><b>Add nodes</b><p>«Add» above the canvas: each node has an icon and a line on what it’s for. If a node is selected, the new one goes next to it and links to it by itself when the ports match: select the Idea and add a Writer, and «text» goes into «idea». With nothing selected, the node goes to the middle of the screen. «Templates» is a ready piece of graph. Nodes move with the mouse, the panel on the right edits the selected one.</p></li>
  <li><b>Watch «Next»</b><p>The selected node’s panel has «Next»: the next step for that very node («Connect the Idea», «Press «Write»», «Expand into scenes», «Connect «scene» to a Join»). What a node is missing also shows on the card itself, as a dashed badge.</p></li>
  <li><b>Link the ports</b><p>Drag from an output on the right to an input on the left <b>of the same color</b>: text to text, picture to picture. A square input takes several links, a round one takes one: a new link replaces the old.</p></li>
  <li><b>Shoot</b><p>«Shoot all» in the project panel shoots what the outputs need and takes the rest from the cache. «Shoot up to here» on a node shoots only it and what it needs.</p></li>
  <li><b>Try versions</b><p>«Another take» on a scene, «Duplicate branch» for a second ending, several outputs for several versions of the video.</p></li>
</ol>
<h3>Keys</h3>
<div class="keys-grid">
  <span><kbd>Shift</kbd> + box</span><span>select several nodes</span>
  <span><kbd>Ctrl</kbd> + click</span><span>add a node to the selection</span>
  <span><kbd>Ctrl</kbd> <kbd>A</kbd></span><span>select all</span>
  <span><kbd>Esc</kbd></span><span>clear the selection</span>
  <span><kbd>Delete</kbd> <kbd>Backspace</kbd></span><span>delete the selection</span>
  <span><kbd>Ctrl</kbd> <kbd>C</kbd> · <kbd>Ctrl</kbd> <kbd>V</kbd></span><span>copy and paste, with the links between the nodes</span>
  <span><kbd>Ctrl</kbd> <kbd>D</kbd></span><span>duplicate the selection</span>
  <span><kbd>Ctrl</kbd> <kbd>Z</kbd></span><span>undo</span>
  <span><kbd>Ctrl</kbd> <kbd>Shift</kbd> <kbd>Z</kbd> · <kbd>Ctrl</kbd> <kbd>Y</kbd></span><span>redo</span>
  <span><kbd>?</kbd></span><span>the key sheet, the same list in a separate window (the «Keys» button above the canvas)</span>
</div>
<p class="note">The keys work on any keyboard layout. In an input field they belong to the field: <kbd>Ctrl</kbd> <kbd>A</kbd> there selects the text. One undo step is one save of the graph; a pause in typing is a step too.</p>
<h3>More</h3>
<dl>
<dt data-term="Снять всё">Shoot all</dt><dd>One job in the queue. The order: pictures, then scenes (scenes of one model in a row and scenes with Ref2VA in a row, to switch models less often), «Video → video», «Scene sound», frames, joins and montages, music, outputs. An error stops only its own branch; the others get finished. «Stop after the current node» works as on the «Video» screen.</dd>
<dt data-term="Снять до сюда">Shoot up to here</dt><dd>On the selected node: shoots it and everything it needs, and nothing after it.</dd>
<dt data-term="Кэш и ключи">Cache and keys</dt><dd>Each scene has a key made of the prompt (in the form the model will get it), the seed, size, length, model, LoRA, the start and last frame, the photo for Ref2VA and the voice sample — the same as in the storyboard. Edit a scene and its key changes, along with the keys of everything that starts from its frame; neighboring branches are untouched. A node with a new key shows «to shoot».</dd>
<dt data-term="Сценарист и герой">Writer and hero</dt><dd>They work only by button: «Write», «Describe from photo». If an input changed, the node is marked «Rewrite». «Rewrite outdated» on the right runs all such nodes in one job, so the Writer’s model loads once.</dd>
<dt data-term="Длина сцены">Scene length</dt><dd>Each scene has its own: 3–15 s, but no longer than the graph’s model shoots (LTX 10 s, WAN 5 s); 5 by default (a slider and 3 · 5 · 8 · 10 · 15 buttons in the scene panel). The length is part of the key: change it and the scene will be reshot. The timeline of the prompt fields stretches to the length of the scene it feeds; «Frame at a moment» stays within that scene’s length. H3 was trained on 5–15 s: 3–4 s will shoot, but it’s outside what it’s used to.</dd>
<dt data-term="Реплики">Lines</dt><dd>The «Prompt» panel has a «Lines» section: who speaks, how and what, in the video’s language. «Who» is how the hero is named in the prompt: <code>The heroine</code>, <code>Character 2</code>, <code>The man</code> (suggestions come from the text). The server inserts the line into the timeline as a separate row (<code>[1s-3s] The man says with a smile, in Russian: "…"</code>), and the voice goes first in the <code>Audio:</code> line; on the scene, «Prompt with lines» shows what the model will get. About 2 words per second of the scene. «Suggest»: the Writer reads the prompt and suggests lines for those in it (by button). Lines from the storyboard via «Copy — project graph» and from the Writer via «Expand into scenes» land here too, and the scene keys don’t change.</dd>
<dt data-term="Дрейф лица">Face drift</dt><dd>With people, the face slowly drifts if scenes keep starting from the previous one’s frame. As in the storyboard, after three continuations in a row a scene shows «face may drift»: start a new scene or connect the hero’s photo to the «faces» input — Ref2VA (H3 only) checks the face against the photo, and the count starts over. With no people in the prompt, there is no warning.</dd>
<dt data-term="Дубли">Takes</dt><dd>«Another take» on a scene shoots it again with a different seed. All takes are kept in the cache; the chosen one goes into the join and into the continuations after it. «Clear takes» moves the unchosen takes and the files no node refers to anymore to the Windows Recycle Bin.</dd>
<dt data-term="Дублировать ветку">Duplicate branch</dt><dd>Copies a node and everything after it, with the copied scenes’ prompts and the links that enter the branch from outside. This is how scene 3 becomes a second ending: a copy of the scene, its own join and its own output, while scenes 1–2 are shared and shot once.</dd>
<dt data-term="Упорядочить">Arrange</dt><dd>A button above the canvas: the nodes line up along the flow from left to right — idea and heroes, prompts, scenes, join and output; what only feeds another node (a track, LoRA, a photo) goes right before it. Each chain of scenes gets its own row, many chains go into several columns, the video’s tail on the right. A group is arranged inside and placed as a block, its frame fits itself; notes go in a row at the top. With two or more nodes selected, only they are arranged. Ctrl+Z puts things back.</dd>
<dt data-term="Шаблоны">Templates</dt><dd>The «Templates» button above the canvas opens a window: each template has a thumbnail graph, what’s in it («4 scenes · 2 outputs · track»), «Insert» and «JSON». There are 16 built in, from simple to complex: «Idea → Writer → video» (the first), a chain of three scenes, two endings, a short and a long version, animate a photo, picture → scene, one face in different places (Ref2VA), a dialogue of two, another angle from the middle, three takes and the best one, your own style via LoRA, a clip to your own track, a trailer from five places, a landscape as one chain, Writer, Writer and a face from a photo. Each has a note on what to do first. On the home screen, «Graph» → «Choose a template» opens the same window: a graph from a template or an empty one.</dd>
<dt data-term="Шаблоны в JSON">Templates as JSON</dt><dd>«Save as template»: the selected nodes (or the whole graph) become your template in <code>data\\graph_templates</code>. «Download as JSON» and «JSON» on the card give a file you can edit, pass to someone or keep. «Load from JSON» turns a file into your template again; a taken name gets «(2)», nodes of unknown types and links between ports of different colors are skipped, and a message says how many. A project’s <code>graph.json</code> is accepted too. Project files (photos, tracks) and the Writer’s result don’t go into a template; load them into the nodes again.</dd>
<dt data-term="Собрать раскадровку">Build a storyboard</dt><dd>Only from a straight graph: one output, one join, each scene 5 s long starting from nothing, from a photo or from the previous scene, the same LoRA everywhere. Ref2VA faces become storyboard heroes with photos (a hero from a «Hero» node keeps its look), and each scene remembers its faces in their order. The result is a new storyboard with its own prompts, the same seeds and keys; the shot scenes are already in it.</dd>
</dl>` },

  { id: 'graph-nodes', group: 'Graph', title: 'Graph nodes', html: `
<p class="lead">Each node does one thing. The header’s color is who does the work, a port’s color is what goes through it; only ports of the same type can be linked («scene» and «video» share one color, blue, but can’t be linked).</p>
<div class="legend-row">${WHO_CHIPS}</div>
<div class="legend-row">${PORT_CHIPS}</div>
<h3>Writer</h3>
<dl class="node-cards">
${nodeCard('Идея', 'Idea', 'user', 'bulb', [], [['text', 'text', 'a couple of sentences in your language, into the Writer’s «idea» input']], 'What the video is about, in your language (set on «Models» → «Writer»). «Turn into a prompt» is for when you want to shoot the idea right away, without the Writer: it translates the idea into an English prompt for the graph’s model, a «Prompt» node appears next to it, and the idea’s links to scenes and pictures move to that node.')}
${nodeCard('Герой', 'Hero', 'writer', 'user', [], [['look', 'look', 'the hero’s description, into the Writer’s «heroes» input'], ['picture', 'image', 'the hero’s photo, into a Scene’s «faces» input (Ref2VA)']], 'Photo, gender, age, look and outfit in English. «Describe from photo» fills them in by button. You can describe the hero in your language and press «Translate to English»: the Writer splits the description into look and outfit.')}
${nodeCard('Сценарист', 'Writer', 'writer', 'quill', [['idea', 'text', 'what the video is about, from an «Idea» node'], ['heroes', 'look', 'who is in the frame, from «Hero» nodes, several if you like']], [], 'Writes a storyboard from the idea and the heroes («Write»). «Expand into scenes» places prompts and scenes, a join and an output to the right; after «Rewrite», the same nodes get new texts and keep their seeds.')}
</dl>
<h3>Scenes</h3>
<dl class="node-cards">
${nodeCard('Промт', 'Prompt', 'user', 'text', [], [['text', 'text', 'an English prompt, into the «prompt» input of a Scene, a Picture or «Video → video»']], 'What is in the frame and what the heroes say, for the graph’s model (H3, LTX or WAN), as text or by fields, as in the Lab. The line «Continue seamlessly from &lt;Picture 1&gt;.» is added by itself if the scene starts from a frame. «Lines»: what the heroes say, in the video’s language; they go into the timeline and the sound.')}
${nodeCard('Фото', 'Photo', 'user', 'image', [], [['picture', 'image', 'into a Scene’s «start»: the first frame (cropped to the frame); into «faces»: a face for Ref2VA']], 'Your picture from disk.')}
${nodeCard('Картинка', 'Picture', 'krea', 'brush', [['text', 'text', 'what to draw, from a «Prompt» or an «Idea»'], ['refs', 'image', 'FLUX.2 Klein only: a photo, a hero or another picture (up to three); Krea 2 has no such input']], [['picture', 'image', 'the drawn frame, into a Scene’s «start»']], '<p>Draws a frame for a Scene’s «start». The model is set in the «Who draws» field.</p><ul class="nc-opts"><li><b>Krea 2</b>From the prompt alone, at the video’s final frame size (a draft scene takes it scaled down). About 3.5 s (the first picture after video about 10 s). A Krea LoRA with a strength can be added.</li><li><b>FLUX.2 Klein</b>From the prompt, from the pictures on the «refs» input, or from both, about 4 s:<ul><li>without references — a picture from the text;</li><li>with references — the same face, hair and clothes in a new place and angle;</li><li>an edit of the picture itself: «replace the background with a beach, the rest the same» — the translator keeps the reference’s frame;</li><li>with no prompt — a new photo of the person in the first reference.</li></ul>In the prompt the references are «the first image», «the second image». Its own LoRA comes from the folder in «Models and settings» → FLUX.2 Klein.</li></ul><p class="nc-note">A prompt that feeds both a Scene and a Picture is translated twice: for the scene in the video model’s form, for the picture as a still for its model (the Prompt’s «For the picture» field).</p>')}
${nodeCard('Сцена', 'Scene', 'h3', 'clapper', [['prompt', 'text', 'what is in the frame and what is said, from a «Prompt» node'], ['start', 'image', 'the first frame: a «Photo», a «Picture» or the «Frame» of the previous scene'], ['end', 'image', 'the frame the scene arrives at, LTX only'], ['faces', 'image', 'the hero’s photo: Ref2VA keeps the face, H3 only'], ['LoRA', 'lora', 'LoRA sets from a «LoRA» node; a LoRA from a sample also changes the model that shoots'], ['scene', 'clip', 'the sample clip for IC-LoRA and Ref2VA LoRA: its length and frame are used'], ['voice', 'audio', 'the voice sample for ID-LoRA, from a «Track» or a «Scene sound»']], [['frame', 'image', 'the last frame, into the «start» of the next scene'], ['scene', 'clip', 'the shot clip, into a Join, a Montage, a Frame, a Scene sound or «Video → video»']], '<p>Shot by the graph’s model: H3 3–15 s, LTX up to 10 s, WAN 5 s without sound; 5 s by default. Without a «start» it is shot from the prompt alone, with a «start» from the picture, with an «end» it arrives at the picture.</p><p><b>From a sample.</b> A LoRA that reads a sample goes into the «LoRA» input (in the «LoRA» node, the «From a sample» group), and the scene is shot by that LoRA’s model:</p><ul class="nc-opts"><li><b>IC-LoRA and H3’s Ref2VA LoRA</b>Remake the clip from the «scene» input: Alpha-Gen, 3DREAL, CrossView, upscale.</li><li><b>LTX 2.3’s ID-LoRA</b>Shoots a talking hero: the face from «start», the voice from a piece of a «Track» in the «voice» input (from which second and how long is in the scene panel, 5 s is best). The prompt is in [VISUAL] / [SPEECH] / [SOUNDS] or plain text with lines. WeSpeaker measures how close the voice is to the sample: «sounds like it» from 0.6, «doesn’t» below 0.4, «partly» in between; music in the sample lowers the score.</li></ul><p class="nc-note">The shot clip is checked as in the storyboard: «In the clip: …» in the panel and a badge on the node. Takes, continuations and montage work as for any scene.</p>')}
${nodeCard('Видео → видео', 'Video → video', 'v2v', 'film', [['scene', 'clip', 'the clip to remake, from a Scene or another «Video → video»'], ['prompt', 'text', 'if the LoRA asks for a prompt, from a «Prompt» node'], ['picture', 'image', 'the character to swap in (Character-Swap), from a «Photo»'], ['LoRA', 'lora', 'LoRA with strengths, from a «LoRA» node']], [['scene', 'clip', 'the remade clip, into a Join, a Montage, a Frame or the next «Video → video»']], '<p>The clip again, through a LoRA that reads the clip itself. The LoRA is chosen in the node:</p><ul class="nc-opts"><li><b>IC-LoRA for LTX 2.5</b>Alpha-Gen removes the background, Restore, Deblur…</li><li><b>IC-LoRA for LTX 2.3</b>3DREAL turns a 3D render photorealistic, CrossView gives another camera position, upscalers make the clip bigger.</li><li><b>Ref2VA for H3</b>Character-Swap replaces the hero with the character from the picture.</li></ul><p><b>Transparent background.</b> Alpha-Gen gives a mask and a clip with a transparent background. In the node panel it downloads for editing (MOV ProRes 4444: DaVinci, Premiere) and for the web (WebM: browsers, OBS). A regular player doesn’t show transparency and plays the whole clip.</p><p class="nc-note">How to run a LoRA comes from its profile: whether it needs a prompt and what word the prompt starts with, one or two stages, how many frames at a time, how many times bigger the result is than the clip. Your own profile is a &lt;name&gt;.v2v.json file next to the LoRA. A clip longer than the LoRA takes at once goes in pieces. Such LoRA don’t go into scenes: there they give a flat picture.</p>')}
${nodeCard('Лица', 'Faces', 'facefix', 'face', [['scene', 'clip', 'the shot clip, from a Scene or «Video → video»'], ['prompt', 'text', 'who is in the frame: the hero’s look in English, from a «Prompt» or typed in the panel']], [['scene', 'clip', 'the clip with its faces fixed, into a Join, a Montage or further on']], '<p>Small, far faces in a shot scene made sharp and steady from frame to frame. About 2 min per 5 s scene, both models loading included. No faces in the clip: a copy of the clip and a note.</p><ul class="nc-opts"><li><b>Which faces</b>By the face’s width in the frame: «far» (the default) are fixed fully up to 7 % of the frame’s width and fade out by 9 %; «very far» 4–6 %, «far and medium» 10–12 %, «all». A large face is left alone: the model draws it worse than it was shot.</li><li><b>Who is in the frame</b>The hero’s look, as the Writer has it. With it the models draw the hero, not someone alike: without a description and with a strong redraw the face became a stranger’s.</li></ul><p class="nc-note">The face is tracked frame by frame (YuNet), a 512×512 square around it. Anchor frames every 16 frames are enhanced by Krea 2 (img2img, denoise 0.3), the whole crop goes through LTX 2.3 with little noise (σ 0.72, 2 steps, the anchors as guides) and is blended back under a soft oval with the colour shifted towards the original.</p>')}
${nodeCard('Кадр', 'Frame', 'ffmpeg', 'crop', [['scene', 'clip', 'the clip, from a Scene or «Video → video»']], [['picture', 'image', 'a frame of the clip, into another Scene’s «start»']], 'A frame from a scene: the last one or at any moment within its length. A continuation doesn’t have to start from the end.')}
${nodeCard('Звук сцены', 'Scene sound', 'ffmpeg', 'volume', [['scene', 'clip', 'the shot scene whose sound to take']], [['track', 'audio', 'the scene’s voice, into the «voice» of the next Scene (ID-LoRA) or the «track» of Music']], 'The sound of a shot scene, by default only the voice (Demucs separates it from music and noise, ~1 min on the GPU). So the hero speaks in the same voice throughout the video.')}
${nodeCard('LoRA', 'LoRA', 'user', 'sliders', [], [['LoRA', 'lora', 'a set with strengths, into the «LoRA» input of a Scene or «Video → video»']], 'A set of LoRA with strengths. The LoRA belong to the graph’s model (H3, LTX or WAN), from its folder. A scene can have several sets, different scenes different ones.')}
</dl>
<h3>Video</h3>
<dl class="node-cards">
${nodeCard('Склейка', 'Join', 'ffmpeg', 'merge', [['scenes', 'clip', 'clips in order, from Scenes and «Video → video», as many as you like']], [['video', 'video', 'the joined video, into Music or an Output']], 'Scenes in order (the order is in the panel on the right). A continuation from its own last frame is joined without repeating the frame. Sound is cut in whole frames together with the picture and isn’t shifted, as in the montage; at a cut, 0.03 s of smoothing prevents clicks. «Make a montage» turns it into the same node with a montage editor.')}
${nodeCard('Монтаж', 'Montage', 'ffmpeg', 'cut', [['scenes', 'clip', 'clips for the montage, from Scenes and «Video → video», as many as you like']], [['video', 'video', 'the edited video, into Music or an Output']], 'A join with an editor, the same one the storyboard has: trimming, splitting (S), copies, speed, transitions, scene takes, sounds from files, undo. «Open montage» in the node panel; the montage is stored in the node, each branch has its own. «Video → video» clips come each as a separate clip, without takes. The track comes from a «Music» node after it.')}
${nodeCard('Трек', 'Track', 'user', 'music', [], [['track', 'audio', 'an audio file, into Music’s «track» or a Scene’s «voice» (a voice sample, 5–10 s of clean speech is best)']], 'Your audio file: mp3, wav, m4a, flac or ogg, or «Record voice» from the microphone.')}
${nodeCard('Музыка', 'Music', 'ffmpeg', 'mix', [['video', 'video', 'from a Join or a Montage'], ['track', 'audio', 'from a «Track» or a «Scene sound»']], [['video', 'video', 'the video with music, into an Output']], 'The track over the video: track and scene sound volume, from which second of the track, fade-in and fade-out.')}
${nodeCard('Выход', 'Output', 'ffmpeg', 'export', [['video', 'video', 'from a Join, a Montage or Music']], [], 'The finished file: as shot, 1080p or 4K via RTX, HDR10, 48 frames per second. There can be several outputs, each its own version.')}
</dl>
<h3>On the canvas</h3>
<dl class="node-cards">
${nodeCard('Заметка', 'Note', 'none', 'note', [], [], 'Text on the canvas; it does nothing.')}
${nodeCard('Группа', 'Group', 'none', 'box', [], [], 'A titled frame behind nodes. Drag it by its header and the nodes inside move with it.')}
</dl>` },

  { id: 'video-models', group: 'Shooting and video', title: 'Video models: H3, LTX, WAN', html: `
<p>The video model is chosen at creation and changed in the storyboard panel («Model») or the graph’s; a scene can have its own («Model» in the scene inspector). All models run on one worker: at the first scene of another model, the previous one unloads and the new one loads, up to half a minute extra.</p>
<div style="overflow-x:auto;margin:6px 0 18px"><table style="border-collapse:collapse;font-size:13.5px;line-height:1.45;min-width:640px">
<thead><tr style="text-align:left;color:var(--text)"><th style="padding:6px 10px 6px 0">Model</th><th style="padding:6px 10px">Good for</th><th style="padding:6px 10px">Sound and voice</th><th style="padding:6px 10px">Scene up to</th><th style="padding:6px 10px">Draft / final, 16:9</th><th style="padding:6px 10px">5 s scene, draft</th><th style="padding:6px 0 6px 10px">LoRA</th></tr></thead>
<tbody style="color:var(--soft)">
<tr style="border-top:1px solid var(--rule)"><td style="padding:6px 10px 6px 0"><b>MiniMax H3</b></td><td style="padding:6px 10px">faces and acting, faces from a photo (Ref2VA)</td><td style="padding:6px 10px">own sound, lines in the video's language</td><td style="padding:6px 10px">15 s</td><td style="padding:6px 10px">960×544 / 1344×768</td><td style="padding:6px 10px">≈ 95 s</td><td style="padding:6px 0 6px 10px"><code>loras\\h3</code></td></tr>
<tr style="border-top:1px solid var(--rule)"><td style="padding:6px 10px 6px 0"><b>LTX 2.5</b></td><td style="padding:6px 10px">fast scenes with sound; «arrive at a frame»</td><td style="padding:6px 10px">own sound, lines</td><td style="padding:6px 10px">10 s</td><td style="padding:6px 10px">1024×576 / 1280×704</td><td style="padding:6px 10px">≈ 29 s</td><td style="padding:6px 0 6px 10px"><code>loras\\ltx25</code></td></tr>
<tr style="border-top:1px solid var(--rule)"><td style="padding:6px 10px 6px 0"><b>LTX 2.3</b></td><td style="padding:6px 10px">clips: shoots to your track, heroes sing; a hero’s voice from a sample (ID-LoRA); «arrive at a frame»</td><td style="padding:6px 10px">own sound, lines</td><td style="padding:6px 10px">10 s</td><td style="padding:6px 10px">1024×576 / 1280×704</td><td style="padding:6px 10px">≈ 32 s</td><td style="padding:6px 0 6px 10px"><code>ltx\\loras</code>, <code>ltx\\ic-loras</code></td></tr>
<tr style="border-top:1px solid var(--rule)"><td style="padding:6px 10px 6px 0"><b>WAN 2.2 5B</b></td><td style="padding:6px 10px">picture only; Apache-2.0 license, fine for commercial use too</td><td style="padding:6px 10px">none</td><td style="padding:6px 10px">5 s</td><td style="padding:6px 10px">960×544 / 1280×704</td><td style="padding:6px 10px">≈ 120 s</td><td style="padding:6px 0 6px 10px"><code>loras\\wan5b</code></td></tr>
<tr style="border-top:1px solid var(--rule)"><td style="padding:6px 10px 6px 0"><b>WAN 2.2 5B · FastWan</b></td><td style="padding:6px 10px">the same as WAN, several times faster: 8 steps instead of 20</td><td style="padding:6px 10px">none</td><td style="padding:6px 10px">5 s</td><td style="padding:6px 10px">960×544 / 1280×704</td><td style="padding:6px 10px">≈ 40 s</td><td style="padding:6px 0 6px 10px">same as WAN</td></tr>
</tbody></table>
<p class="note">Times are measured on an RTX 4080 with the model already in memory; «Models and settings» shows this machine’s measurements. The LoRA folders are in <code>models\\loras</code> and are changed there too. In the storyboard, scenes are 5 s each, 10 s on LTX.</p></div>
<dl>
<dt data-term="LTX: две стадии">LTX: two stages</dt><dd>LTX 2.5 and 2.3 shoot at half size, then upscale the latent twice. They don’t keep faces from a photo: the face is held by words and the start frame.</dd>
<dt data-term="WAN без звука">WAN without sound</dt><dd>Lines won’t be heard; the video’s only sound is your track. Silence goes into clips without a track, so the join and the montage work as usual.</dd>
<dt data-term="Промт под модель">Prompt per model</dt><dd>The storyboard keeps the H3 prompt, while LTX and WAN get their own, built from the same scene fields following their model’s guide. LTX: one paragraph in the present tense — style, place, who is there, the action from start to finish, camera, sound with lines. WAN: who, where, motion, camera, style, no sound; for a continuation and a scene from a photo, only motion and camera. In the inspector you see this under «Prompt for the model, EN»: «LTX 2.5 will get…». LTX and WAN get a scene’s own prompt reworked: without H3 marks, the timeline as one paragraph, without the tail about lettering, and for WAN without lines and sound. Switching models doesn’t spoil the storyboard: switch back to H3 and what H3 shot comes from the cache.</dd>
<dt data-term="Кэш">Cache</dt><dd>Each model has its own scene keys: what one model shot isn’t mixed up with another. H3’s keys are the same as before the other models appeared.</dd>
<dt data-term="Веса">Weights</dt><dd>«Models and settings» → the model’s section: which files are needed, where they are, where to download them. Without weights, a model is marked «no weights» in the list.</dd>
</dl>` },

  { id: 'shoot', group: 'Shooting and video', title: 'Quality, LoRA, music, output', html: `
<dl>
<dt data-term="Модель">Model</dt><dd>Who shoots the video: H3, LTX 2.5, LTX 2.3, WAN 2.2 5B or WAN 2.2 5B · FastWan. Under the list: what the model won’t do with this storyboard (lines, faces from a photo, sound). Switching models reshoots the scenes; what another model shot stays in the cache. Details in the «Video models» section.</dd>
<dt data-term="Снимать под трек">Shoot to the track</dt><dd>LTX 2.3 only, when your own track is loaded. Each scene gets the piece of the track from where it sits in the video and is shot to it: motion to the music, lips to the song’s vocals. The video’s sound is the track itself. Editing the track or its start reshoots the scenes. The pieces are counted from the storyboard: if you reorder, trim or speed up scenes in the montage, the picture and the song will drift apart.</dd>
<dt data-term="Качество">Quality</dt><dd><b>Draft</b> is smaller and faster, <b>Final</b> is bigger and noticeably more detailed. Size and time differ per model (the table in <a href="#/help/video-models">«Video models»</a>): on H3 the draft is 960×544, about 1.5 min per 5 s scene, the final 1344×768, about 4.5 min; on LTX the final at 1280×704 takes about a minute. The final is shot with the same seeds, so the scenes are the same, only sharper. Handy: first a draft, fix things, then the final.</dd>
<dt data-term="LoRA">LoRA</dt><dd>Fine-tunes of the video model; each model has its own folder inside the models folder: H3 <code>loras\\h3</code>, LTX 2.3 <code>loras\\ltx23</code>, LTX 2.5 <code>loras\\ltx25</code>, WAN and FastWan share <code>loras\\wan5b</code>, Krea 2 <code>loras\\krea2</code> (the folders are changed in «Models and settings»). Put a .safetensors into the folder and the LoRA shows up in the list by itself. «+ from library» shows the video model’s LoRA, the slider is the strength, × removes it. 0.6–1 is usually enough; higher, and the LoRA’s style overrides the prompt. Changing a LoRA or its strength reshoots the whole video. If you switch the video model, the other model’s LoRA stay in the list but don’t act (a yellow line), and scenes with their own model (a clip) take only their own.</dd>
<dt data-term="LoRA картинок">Picture LoRA</dt><dd>Next to the drawing buttons — a «LoRA» line: the picked LoRA as chips, the chip's fill is the strength (drag along it or ← →, × — remove) and «+ add» with the library's list: at the hero (under «What to change»), at the places and at a scene's first frame (the «Start» tab); the same LoRA are in the shooting panel too, under the video's LoRA. «Portraits and places (Krea 2)» — Krea 2 draws the hero's tries and portrait and the places' pictures with them; «Scene frames (FLUX.2 Klein)» — FLUX.2 Klein draws the scenes' first frames («Draw a frame», «Redraw the frame», «Draw frames for all scenes») and adjusts the hero's features with them. Krea LoRA live in <code>loras\\krea2</code>, FLUX.2 LoRA in <code>loras\\flux2</code>. What is drawn already doesn't change — draw it again. When a video is created all of it is in the «LoRA» card under «Model» («Clip from a song», «Writer»): folded, it shows what is picked («Video: none», «Portraits: …», «Scene frames: …»); open, three rows: the video (the video model's LoRA, every scene), the portraits (Krea 2: heroes, places), the scene frames (FLUX.2 Klein). A row of pictures not drawn after the script dims; its picks stay.</dd>
<dt data-term="Музыка">Music</dt><dd>Your own track for the whole video: mp3, wav, m4a, flac or ogg goes on as one track after the join.
<br><b>Track volume</b>: 0–150 %. <b>Scene sound</b>: how much of the scenes’ sound to keep under the music (at 30 % steps and wind are audible). <b>Start track at</b>: from which second. <b>Fade out at the end</b>: a smooth exit.
<br>Changing the track or the levels doesn’t reshoot scenes: the button becomes «Mix the music», which takes seconds. The exception is «Shoot to the track»: there, editing the track or its start reshoots the scenes.</dd>
<dt data-term="В сценах без музыки">No music in scenes</dt><dd>The model stops composing music in every scene and makes only sounds, so they don’t clash with your track. It changes the prompts, so the scenes will be reshot.</dd>
<dt data-term="Выход">Output</dt><dd><b>As shot</b>: no upscaling. <b>1080p</b> and <b>4K</b>: NVIDIA RTX Video upscaling after the join, ~10–15 s per 30 s of video.
<br><b>HDR10</b>: RTX TrueHDR, for watching on an HDR screen; on a regular one it looks washed out.
<br><b>48 frames per second</b>: RIFE draws in-between frames, motion gets smoother; frames aren’t blended at the cuts to new scenes.
<br>Changing the output doesn’t reshoot scenes: the button becomes «Rebuild».</dd>
<dt data-term="Главная кнопка">Main button</dt><dd>Changes with the situation: «Shoot video», «Build video» (everything is shot), «Mix the music», «Rebuild», «Open video». Under it: how many scenes come from the cache and how many have to be shot.</dd>
</dl>` },

  { id: 'cache', group: 'Shooting and video', title: 'Cache and time', html: `
<p>Each shot scene is kept in <code>projects/&lt;video&gt;/scenes</code> under a key made of everything that defines it: the prompt (the one the model will get), seed, size, length, model, LoRA, the start and last frame, the photo for Ref2VA, the voice sample, the piece of the track with «Shoot to the track». If nothing changed, the scene comes from the cache instantly.</p>
<dl>
<dt data-term="Переснимается">Reshot</dt><dd>An edited scene and the continuations after it (their start frame is now different). The whole video, when you change the model, quality, frame, LoRA, Ref2VA, style or the hero’s look.</dd>
<dt data-term="Не переснимается">Not reshot</dt><dd>Music and output (1080p, 4K, HDR10, 48 fps): only mixing and processing, seconds. Except with «Shoot to the track»: there, editing the track reshoots the scenes.</dd>
<dt data-term="Оценка времени">Time estimate</dt><dd>From the latest shoots on this machine, counting the cache, model loading, the join, music and output.</dd>
</dl>` },

  { id: 'video', group: 'Shooting and video', title: 'The «Video» screen', html: `
<dl>
<dt data-term="Плеер">Player</dt><dd>While shooting, the latest finished scene; afterwards, the whole video. Click a scene below to watch it.</dd>
<dt data-term="Полоса сцен">Scene strip</dt><dd>«from cache»; «87 s», how long it took to shoot; «step 5/8» with a percentage; «waiting for frame», a continuation waits for the previous scene; «postponed», after a stop.</dd>
<dt data-term="Остановить после текущей сцены">Stop after the current scene</dt><dd>The current scene finishes and is saved; the rest wait for the next run.</dd>
<dt data-term="Остановить сразу">Stop now</dt><dd>Interrupts the shoot; the current scene is lost.</dd>
<dt data-term="Скачать MP4, Открыть папку">Download MP4, Open folder</dt><dd>The finished video (the name carries the format, e.g. <code>_4k_hdr_48fps</code>) and the project folder.</dd>
<dt data-term="Этапы">Stages</dt><dd>The list above the buttons: «Model and encoder» (starting, loading or «in memory»), «Scenes 1–N» with the count shot, «Join and sound» (or «Join from the montage»), «Music: …» if there is a track, and the output if it isn’t «as shot».</dd>
<dt data-term="Главная кнопка">Main button</dt><dd>Depending on the situation: «Shoot video», «Shoot what changed» (some scenes are already shot), «Build from the montage» (the montage changed), «Remix the music», «Rebuild: …» (the output changed) or «All shot». Under the label: the quality and the time estimate.</dd>
<dt data-term="Монтаж">Montage</dt><dd>A button next to «Open folder»: trim scenes, reorder, transitions, sounds, and build again (the «Montage» section).</dd>
<dt data-term="Снять финал, Снять черновик">Shoot final, Shoot draft</dt><dd>The same scenes with the same seeds in a different quality; the size differs per model and is in the button’s tooltip (on H3 the final is 1344×768). Next to it, the time estimate.</dd>
</dl>` },

  { id: 'lab', group: 'Tools', title: 'Lab', html: `
<p>The <code>/lab</code> page: one scene by hand, without a storyboard. Handy for trying prompts, start frames, LoRA and models.</p>
<dl>
<dt data-term="Модель">Model</dt><dd>The button with the model’s name above the frame on the right: who shoots the take — H3, LTX 2.5, LTX 2.3, WAN 2.2 5B or FastWan. The prompt goes out as written: to H3 word for word, to LTX and WAN without H3 marks (the «How to write a prompt» section). The model determines the size, the length (no longer than its limit) and the LoRA list. The model is labeled on the take.</dd>
<dt data-term="Снять на всех моделях — сравнить">Shoot on all models — compare</dt><dd>A button under «Shoot»: the same prompt and seed, one take on each model whose weights are present. Each model loads in turn, so this takes a few minutes.</dd>
<dt data-term="Промт сцены">Scene prompt</dt><dd>Two switches above the prompt. Language: <b>English</b> is the prompt that goes to the model; <b>Русский</b> (or your texts' language) is the same scene in your language, for translation. English is always what gets shot. View: <b>Fields</b>, the scene in parts, and the prompt builds itself; <b>Text</b>, the whole prompt as your own text. «Preset ▾» fills the fields or inserts text in the language of the open tab.</dd>
<dt data-term="Поля и текст">Fields and text</dt><dd><b>Fields</b>: style, place, camera, what happens second by second, sound and two tail checkboxes; they build an H3-format prompt (you see it in the collapsed «Prompt for …» under the fields). The timeline counts itself, and actions and lines go one per row, so timeline mistakes have nowhere to come from. <b>Text</b>: one big text with markup, as before, for those who write the prompt themselves or edit the built one («Edit as text»). Going from text to fields splits the text into parts; a paragraph without a label goes into «Place», and the page will say so.</dd>
<dt data-term="Стиль">Style</dt><dd>What kind of film it is: live action or animation, light, color, film stock. One sentence; in the English prompt, the first paragraph without a label.</dd>
<dt data-term="Место">Place</dt><dd>Where and when, who is there and what they look like: a room or a street, time of day, weather, people with age, hair and clothes. Becomes the <code>Scene:</code> line.</dd>
<dt data-term="Камера">Camera</dt><dd>Shot size and movement from the lists, the same words as in the storyboard; the field below adds your own words («face clearly visible»). Together they become the <code>Camera:</code> line.</dd>
<dt data-term="Что происходит">What happens</dt><dd>Actions one per row, up to six. The time on the left counts itself: the actions split the scene’s length evenly, three actions in 5 s get 2, 2 and 1, as in the storyboard. To make an action last longer, enter the seconds in the field on the right; empty means an even share with the rest. A hero’s line goes in quotes in the same row, and the row gets a pink mark on the left; on the English layer it must be preceded by <code>in Russian:</code> (or your language), which the translation adds by itself.</dd>
<dt data-term="Звук">Sound</dt><dd>What is heard throughout the scene: the sounds of the place and actions, music by instruments and tempo, or «no music». Becomes the <code>Audio:</code> line. The sound of a single event is better written into its action row.</dd>
<dt data-term="Промт для модели">Prompt for the model</dt><dd>A collapsed block under the fields, named after the model — «Prompt for H3», «Prompt for LTX 2.5»: the text built from the fields. LTX and WAN get it without H3 marks. «Edit as text» switches to «Text» mode, where you can rewrite it entirely.</dd>
<dt data-term="Проверка промта">Prompt check</dt><dd>Yellow lines under the field: what’s worth fixing before shooting, each with a button that does it:
<br>unfilled «...»: «Go to»; the timeline is longer or shorter than the scene: «Scene 8 s» or «Fit the timeline» (the times in brackets are recalculated); no timeline: «Add»; non-English words outside quotes, several actions joined by then in one row, walking with no direction toward the camera, lettering in the frame: «Show»; there is a start frame but no «Continue seamlessly from &lt;Picture 1&gt;.» line: «Add line», and the other way round.
<br>These are hints, not a ban: you can shoot as is. Only with unfilled «...» will the program ask again.</dd>
<dt data-term="Заготовка">Preset</dt><dd>The «Preset ▾» menu: 16 whole prompts for common scenes; they are inserted in the language of the open tab, and the scene length is set to fit their timeline:
<br><b>Basics</b>: all parts empty, a hero in the frame, a continuation from a frame (needs a start frame).
<br><b>Speech</b>: a line to the camera, a dialogue of two, a voice-over.
<br><b>People and motion</b>: walks toward the camera, three in the frame, a dance for a clip.
<br><b>Sounds and music</b>: an explosion and effects, a musician in the frame, music off screen.
<br><b>No people</b>: nature, an object in close-up.
<br><b>Style</b>: 3D cartoon, old film.
<br>Change the hero, place and actions to suit you. «A line to the camera» is tested in Remiqora Video; the rest are written following the MiniMax guide, so shoot 2–3 takes each. While there are no takes, the same presets sit on the right, in place of the monitor.</dd>
<dt data-term="Перевести на английский">Translate to English</dt><dd>On the «Русский» tab. The Writer chosen in the header translates the text into an English prompt by the H3 formula: splits it into parts, sets the times <code>[0s-2s]</code> over the scene’s length, keeps lines in quotes as written and adds <code>in Russian:</code> (or your language), so the hero says them in it. The translation opens on the English tab: check it before shooting. The source text stays; if you changed it, a yellow dot appears on the tab — translate again.
<br>Translation takes 10–30 s and runs in the shared GPU queue. The Writer and the video model don’t fit in memory together, so the video model is unloaded for that time, and the next take loads it again (up to half a minute extra). A small model can make mistakes in translation; that’s what the check is for.</dd>
<dt data-term="Как писать промт">How to write a prompt</dt><dd>With examples and ready prompts: the <a href="#/help/prompt">«How to write a prompt»</a> section and the ones after it.</dd>
<dt data-term="Развернуть">Expand</dt><dd>The arrows button at the right above the prompt: the prompt opens across the whole Lab, your language and English side by side, each with its own parts and check. There, too, are «Shoot scene» and a summary of what will be shot. «Collapse» or Esc returns the prompt to the panel.
<br>You can also just make the left panel wider: drag its right edge (or click the edge and press <kbd>←</kbd> <kbd>→</kbd>); a double click on the edge restores the previous width. The width is remembered.</dd>
<dt data-term="Разметка">Markup</dt><dd>A checkbox above the prompt. Each part is labeled in the interface's language above its paragraph («Место: где, когда, кто», «Таймлайн: что по секундам»), the labels <code>Scene:</code>, <code>Camera:</code>, <code>Audio:</code> are in the parts’ colors, times <code>[0s-2s]</code> in green, lines in quotes in pink, <code>&lt;Picture 1&gt;</code> in blue, and «...» still to be filled in purple. Non-English words outside quotes get a red wavy underline: the model understands them worse, so translate them, and put a hero’s line in quotes. The labels are visible only to you; only the prompt goes to the model. Uncheck it and the field becomes a plain one.</dd>
<dt data-term="Части промта">Prompt parts</dt><dd>The line under the prompt: Style, Place, Camera, Timeline, Sound, Tail, in the same colors as in the prompt breakdown at the start of the help. One with a dot means the part is there; a click selects it. A dashed one with a plus means the part is missing; a click inserts its template in its place, with the «...» in it left selected so you can type right away.</dd>
<dt data-term="Стартовый кадр">Start frame</dt><dd>The picture the scene starts from: the model brings it to life and continues it. Drag a file (png, jpg, webp) into the frame on the right or click «Start frame» above it; even easier, «Continue from the last frame» under a finished take. With a frame, write <code>Continue seamlessly from &lt;Picture 1&gt;.</code> as the prompt’s first line.
<br>«Describe the person»: the Writer looks at the frame and describes the look in English (~10 s, the GPU is busy for that time); «Insert into prompt» puts the description where the cursor is. «Remove frame»: the scene is shot from text again.</dd>
<dt data-term="Длина">Length</dt><dd>On the right under the frame: 3, 5, 8 or 10 seconds; any from 1 to 15 s in 0.5 steps in the «other» field next to them. Left of the length is the scene’s ruler with the prompt’s timeline lines on it: you see what happens when and whether something runs past the end (that piece is red); a click on a piece selects its line in the prompt. No longer than the model shoots: LTX 10 s, WAN 5 s (longer buttons are hidden). H3 was trained on scenes from 5 to 15 seconds; shorter can be shot, but it’s outside what it’s used to. Under the length: how many frames you’ll get; the models shoot 24 frames per second and round the length up to their frame grid. The longer the scene, the longer the shoot; the estimate is under the «Shoot» button.</dd>
<dt data-term="Формат">Format</dt><dd>Above the frame: its shape, 16:9 horizontal, 9:16 for a phone, 1:1 square and others. The frame takes that shape at once; in its corner is the size in pixels, which differs per model. «Like the frame» takes the start frame’s shape, so it isn’t cropped.</dd>
<dt data-term="Качество">Quality</dt><dd><b>Draft</b>: smaller and faster, for searching for the prompt. <b>Final</b>: bigger and more detailed, 2–3 times longer. Hover a button: the size and time for 5 seconds with the selected model on this machine. The same seed in the final gives the same scene, only sharper.</dd>
<dt data-term="LoRA">LoRA</dt><dd>Fine-tunes of the model you shoot with (H3, LTX or WAN; FastWan uses WAN’s LoRA): style, character, motion. «Add» opens the list from that model’s folder, with search. The slider is the strength (usually 0.6–1; higher, and the LoRA overrides the prompt), ↺ resets it to 0.8, × turns it off. A yellow label means it may not suit the model (on LTX 2.3, LoRA from LTX-2 19B are marked this way). If a LoRA has a trigger word, put it in the prompt.</dd>
<dt data-term="Сид">Seed</dt><dd>A field above the frame. A number that drives the randomness: the same prompt with the same seed gives the same take. Empty means a new one every time. To see what a prompt edit does, keep the seed the same.</dd>
<dt data-term="Сколько дублей">How many takes</dt><dd>The number to the left of «Shoot»: how many takes to shoot in a row, each with a seed 1 higher. Handy for picking the best of several.</dd>
<dt data-term="Дубли">Takes</dt><dd>On the right under the frame, by prompt: each group shows what happens in the scene, with the takes and their seeds below. Hover and a take plays without sound; a click plays it in the frame. A running shoot shows up in its group with its step.</dd>
<dt data-term="Под дублем">Under a take</dt><dd>«Continue from the last frame» makes it the start for the next scene; «Repeat settings» (new seed) or «Repeat with seed», to change the prompt and see only its difference; «Download», «Delete» (to the Windows Recycle Bin).</dd>
<dt data-term="Остановить">Stop</dt><dd>In the status bar while a take is shooting: stops only the Lab’s takes; the studio’s video keeps shooting.</dd>
</dl>` },

  { id: 'models', group: 'Tools', title: 'Models and settings', html: `
<p>The «Models» page in the header. Sections on the left: «H3 video», «Ref2VA», «LTX 2.5», «LTX 2.3», «WAN 2.2 5B» (with the FastWan LoRA), «Krea 2 — pictures», «Writer», «LoRA», «Tools»; a dot shows whether everything is in place, next to it how much disk space it takes. At the top, all models on disk in one bar. Everything is saved at once, no restart needed.</p>
<dl>
<dt data-term="Карточка модели">Model card</dt><dd>For a video model: what it can do (sound, lines, faces from a photo, to a track), «5 s scene», how long a draft takes on this machine (measured; until something is shot, an estimate), steps, license. Next to it, «in memory» or «unloaded».</dd>
<dt data-term="Выгрузить">Unload</dt><dd>A button next to the name while the model is in memory: frees VRAM; the next shoot loads the model again. The same as «Unload model» in the status bar.</dd>
<dt data-term="Веса по ролям">Weights by role</dt><dd>The main model, text encoder, video and audio VAE, LTX’s latent upscaler, the FastWan LoRA, Ref2VA. Each file shows where it is or where it will be downloaded, and from where, as a Hugging Face link. «Use» switches the model, «Remove» sends the file to the Windows Recycle Bin.</dd>
<dt data-term="Скачать">Download</dt><dd>Files download in the background one at a time. «Stop» keeps what’s downloaded, «Resume» continues from the same place; at the end the size is checked against Hugging Face. A file put into the folder by hand shows up on the page by itself.</dd>
<dt data-term="Сценарист">Writer</dt><dd>The default model, context, GGUF folders and download by Hugging Face link.</dd>
<dt data-term="Krea 2 — картинки">Krea 2 — pictures</dt><dd>Draws the «Picture» node in the graph, on the same worker as video (the official ComfyUI build: Krea 2 Turbo int8, Qwen3-VL 4B fp8 encoder, Qwen-Image VAE; all from Comfy-Org/Krea-2, in the worker’s weight folders). Before a picture the video model is unloaded; Krea stays in memory, and the next pictures take about 3.5 s. Krea has its own LoRA folders: each file is checked by its header — LoRA and LoKr fit, LoHa and DoRA are marked «may not apply», full weights are blocked; trigger words and previews (<code>name.png</code>, <code>name.civitai.info</code>) are shown alongside. LoRA are chosen in the «Picture» node, strength from −30 to 30; if some of a LoRA’s keys didn’t fit the model, you see it after the picture.</dd>
<dt data-term="Папки LoRA">LoRA folders</dt><dd>Each model has its own: «LoRA» holds H3’s folders; the LTX 2.5, LTX 2.3 and WAN 2.2 5B sections have their own (one model’s LoRA don’t fit another), Krea has its own. A .safetensors put into a folder shows up in the list by itself.</dd>
<dt data-term="Токен Hugging Face">Hugging Face token</dt><dd>In the «H3 video» section: needed only for gated models, kept in <code>data\\hf_token</code>. «Save», «Remove».</dd>
<dt data-term="Инструменты">Tools</dt><dd>Paths to the ComfyUI core, its Python, llama-server, ffmpeg and ffprobe, RIFE and RTX Video; each shows whether it was found. «As in .env» restores the value from .env or the default; a new core or Python is picked up from the next shoot.</dd>
<dt data-term="Папки и пути">Folders and paths</dt><dd>«Choose…» opens a Windows dialog; «As in .env» restores the value from the settings file.</dd>
</dl>` },

  { id: 'env', group: 'Tools', title: 'Settings in .env', html: `
<p>The <code>.env</code> file in the program folder (the sample is <code>.env.example</code>). All values have defaults for this machine. Paths and folders are easier to set on the «Models» page: there they are saved to <code>data\\settings.json</code> over <code>.env</code>, without a restart.</p>
<dl>
<dt data-term="H3_MODEL_ROOTS">H3_MODEL_ROOTS</dt><dd>Folders with the weights of all worker models — H3, LTX, WAN, Krea (separated by ;): <code>diffusion_models</code>, <code>text_encoders</code>, <code>vae</code>, <code>loras</code>, <code>checkpoints</code>, <code>latent_upscale_models</code> are looked up in them. Default: <code>models</code> in the app's folder; the installer writes the folder chosen at install into <code>.env</code>. The name dates from when there was only one model.</dd>
<dt data-term="COMFY_DIR, COMFY_PYTHON">COMFY_DIR, COMFY_PYTHON</dt><dd>Where the ComfyUI core and its Python are. By default, our own: <code>engine\\ComfyUI</code> and <code>engine\\.venv</code> (installed by <code>install.bat</code>: the core at a pinned commit, torch with CUDA 13, Demucs and Whisper for song lyrics); until they exist, from Comfy Desktop. There is no ComfyUI server and no port: all models are shot by our own process using the core as a library.</dd>
<dt data-term="COMFY_INPUT, COMFY_OUTPUT">COMFY_INPUT, COMFY_OUTPUT</dt><dd>Working folders for frames and shot scenes.</dd>
<dt data-term="WORKER_LOG">WORKER_LOG</dt><dd>The video model worker’s log, default <code>data\\h3worker.log</code>.</dd>
<dt data-term="H3_UNET, H3_CLIP, H3_VAE, H3_AUDIO_VAE">H3_UNET, H3_CLIP, H3_VAE, H3_AUDIO_VAE</dt><dd>File names of the H3 model, encoder and VAE.</dd>
<dt data-term="H3_TURBO_LORA">H3_TURBO_LORA</dt><dd>The official H3 model's turbo LoRA: 8 steps without CFG. A model with the speed-up built in (TURBO in its name) shoots without it.</dd>
<dt data-term="H3_REF_UNET, H3_REF_LORA, H3_REF_DIR">H3_REF_UNET, H3_REF_LORA, H3_REF_DIR</dt><dd>The Ref2VA model, its turbo LoRA and their folder.</dd>
<dt data-term="LTX25_…, LTX23_…, WAN_…, KREA_…">LTX25_…, LTX23_…, WAN_…, KREA_…</dt><dd>Weight names of the other models: <code>LTX25_UNET</code>, <code>LTX25_CLIP</code>, <code>LTX25_VAE</code>, <code>LTX25_AUDIO_VAE</code>, <code>LTX25_UPSCALER</code>; <code>LTX23_CKPT</code>, <code>LTX23_CLIP</code>, <code>LTX23_LORA</code>, <code>LTX23_UPSCALER</code>; <code>WAN_UNET</code>, <code>WAN_CLIP</code>, <code>WAN_VAE</code>, <code>WAN_FAST_LORA</code>; <code>KREA_UNET</code>, <code>KREA_CLIP</code>, <code>KREA_VAE</code>. Looked up in the <code>H3_MODEL_ROOTS</code> folders; defaults are in <code>.env.example</code>.</dd>
<dt data-term="LORA_DIRS">LORA_DIRS</dt><dd>Folders with LoRA for H3 (separated by ;), default <code>loras\\h3</code> inside the models folder.</dd>
<dt data-term="LTX23_LORA_DIRS, LTX25_LORA_DIRS, WAN_LORA_DIRS, KREA_LORA_DIRS">LTX23_LORA_DIRS, LTX25_LORA_DIRS, WAN_LORA_DIRS, KREA_LORA_DIRS</dt><dd>Each model’s own LoRA folders (separated by ;). Defaults: LTX 2.3 <code>models\\loras\\ltx23</code>, LTX 2.5 <code>models\\loras\\ltx25</code>, WAN and FastWan <code>models\\loras\\wan5b</code>, Krea <code>models\\loras\\krea2</code>.</dd>
<dt data-term="LLAMA_SERVER_BIN, LLM_DIRS, LLM_MODEL, LLM_PORT, LLM_CTX">LLAMA_SERVER_BIN, LLM_DIRS, LLM_MODEL, LLM_PORT, LLM_CTX</dt><dd>The Writer: llama-server, GGUF folders, the default model (gemma-4-E4B), the llama-server port (8191), context length (16384). llama-server is looked up in this order: the given path, <code>tools\\llama</code>, the engine of an installed LM Studio. If Windows blocks it («Smart App Control»), you need a signed build; the easiest is to install LM Studio.</dd>
<dt data-term="FFMPEG, FFPROBE, RTX_VSR, RIFE_BIN, RIFE_MODEL">FFMPEG, FFPROBE, RTX_VSR, RIFE_BIN, RIFE_MODEL</dt><dd>Joining and sound, RTX Video (1080p, 4K, HDR10), RIFE (48 fps) and its model, a folder next to the exe, default <code>rife-v4.6</code>.</dd>
<dt data-term="LYRICS_PYTHON, LYRICS_MODEL">LYRICS_PYTHON, LYRICS_MODEL</dt><dd>Song lyrics (Demucs + Whisper): the Python with them and the Whisper model (<code>large-v3</code>). Python is looked up in this order: the given one (default <code>tools\\lyrics\\.venv</code>), <code>engine\\.venv</code> if it has Demucs, the old Remiqora’s environment.</dd>
<dt data-term="HOST, PORT">HOST, PORT</dt><dd>The program’s address and port: <code>127.0.0.1</code> and 8810.</dd>
</dl>` },
]
